export const RAW_combination_PermissionButtons = `<template>
  <div>
    <div style="margin-bottom: 16px; display: flex; align-items: center; gap: 12px;">
      <span style="color: #606266;">当前角色：</span>
      <el-radio-group v-model="role" size="small">
        <el-radio-button label="admin">管理员</el-radio-button>
        <el-radio-button label="editor">编辑</el-radio-button>
        <el-radio-button label="viewer">访客</el-radio-button>
      </el-radio-group>
      <span style="color: #909399; font-size: 13px;">
        可用权限：{{ allowed.length ? allowed.join('、') : '（无）' }}
      </span>
    </div>

    <el-divider content-position="left">表单按钮（configBtn.permissionValue）</el-divider>
    <es-form
      :model="model"
      :form-item-list="formItems"
      :config-btn="formButtons"
      :layout-form-props="layout"
    />

    <el-divider content-position="left">表格操作按钮（operate btns.permissionValue）</el-divider>
    <es-table :data-source="data" :columns="columns" :options="{ border: true }" />
  </div>
</template>

<script lang="jsx">
/**
 * 权限按钮（组合）—— 按角色控制表单/表格按钮的显隐
 *
 * 关键点：
 *   1. EsForm 的 configBtn、EsTable operate 列 btns 均支持 permissionValue，
 *      渲染时用 checkPermission(permissionValue) 过滤（读取全局 \$EsPlus.permission）
 *   2. 应用初始化时用 configureEsPlus({ permission }) 注入判定函数；这里在组件内
 *      改写共享的 \$EsPlus.permission（闭包读取响应式 role），使切换角色即时联动，
 *      并在卸载时还原，避免污染其它页面
 *   3. permission 函数在按钮渲染期间读取 role（响应式），role 变化触发重渲染重新过滤
 */
import { defineComponent, reactive, ref, computed, inject, onUnmounted } from '@vue/composition-api'
import { Message } from 'element-ui'

const rolePerms = {
  admin: ['user:add', 'user:edit', 'user:delete', 'user:export'],
  editor: ['user:add', 'user:edit'],
  viewer: []
}

export default defineComponent({
  name: 'CombinationPermissionButtons',
  setup() {
    const role = ref('admin')
    const allowed = computed(() => rolePerms[role.value] || [])

    // 改写共享的 \$EsPlus.permission（等价于应用初始化时 configureEsPlus({ permission })）
    const esPlus = inject('\$EsPlus', null) || {}
    const originalPermission = esPlus.permission
    esPlus.permission = (v) => !v || allowed.value.includes(v)
    onUnmounted(() => { esPlus.permission = originalPermission })

    const model = reactive({ keyword: '' })
    const formItems = [
      { prop: 'keyword', label: '关键字', span: 12, formtype: 'Input', attrs: { placeholder: '搜索用户' } }
    ]
    const formButtons = [
      { name: '新增', key: 'add', type: 'primary', permissionValue: 'user:add', click: () => Message.success('新增') },
      { name: '批量导出', key: 'export', permissionValue: 'user:export', click: () => Message.success('导出') }
    ]

    const data = reactive([
      { id: 1, name: '张三', dept: '研发部' },
      { id: 2, name: '李四', dept: '市场部' }
    ])
    const columns = [
      { prop: 'id', label: 'ID', width: 80 },
      { prop: 'name', label: '姓名', width: 140 },
      { prop: 'dept', label: '部门' },
      {
        prop: 'operate',
        label: '操作',
        width: 160,
        btns: [
          { name: '编辑', type: 'primary', permissionValue: 'user:edit', clickEvent: (row) => Message.success(\`编辑 \${row.name}\`) },
          { name: '删除', type: 'danger', permissionValue: 'user:delete', clickEvent: (row) => Message.success(\`删除 \${row.name}\`) }
        ]
      }
    ]

    const layout = { formLayProps: { labelWidth: '80px', size: 'small', inline: true } }

    return { role, allowed, model, formItems, formButtons, data, columns, layout }
  }
})
</script>
`
export const RAW_combination_QueryFormLinkage = `<template>
  <div>
    <!-- 查询表单区域 -->
    <div class="query-section">
      <es-form
        :form-item-list="queryFormItems"
        :model="queryFormData"
        :layout-form-props="{ formLayProps: { size: 'mini' }, rowLayProps: { gutter: 10 } }"
        :configBtn="configBtn"
      />
    </div>

    <!-- 数据表格 -->
    <es-table
      ref="tableWithQuery"
      :columns="tableColumns"
      :data-source="tableData"
      :pagination="pagination"
      :options="{
        border: true,
        stripe: true,
        tabHeight: 250,
        heightType: 'height',
        isInitRun: true,
        apiParams: {
          url: 'https://dummyjson.com/users',
          method: 'get'
        },
        httpRequest: (params) => this.requestUsers(params),
        configTableOut: {
          total: 'total',
          pageSize: 'limit',
          tableData: 'users'
        }
      }"
    />
  </div>
</template>

<script lang="jsx">
/**
 * 查询表单联动 —— 演示「表单条件 → 表格数据」的联动
 *
 * 关键点：
 *   1. 表单与表格是兄弟节点：表格不会自动收集表单值，筛选条件统一由 requestUsers
 *      读取组件上的 queryFormData；查询按钮再调 \`httpRequestInstance(model, { keepPage: false })\`
 *      回到第 1 页（keepPage=false 表示搜索语义）
 *   2. \`watch(queryFormData, deep)\` 让条件变化自动触发查询（与页面描述一致）
 *   3. 筛选在 \`httpRequest\` 里真正作用于数据，而不是只改 URL 参数
 */
export default {
  data() {
    return {
      queryFormData: {
        name: '',
        gender: '',
        birthRange: []
      },
      configBtn: [
        { name: '查询', type: 'primary', click: () => this.handleSearch() },
        { name: '重置', click: (model, formRef) => formRef && formRef.resetFields() }
      ],
      queryFormItems: [
        { prop: 'name', label: '姓名', span: 6, formtype: 'Input', attrs: { placeholder: '请输入姓名' } },
        {
          prop: 'gender',
          label: '性别',
          span: 6,
          formtype: 'Select',
          dataOptions: [
            { label: '全部', value: '' },
            { label: '男', value: 'male' },
            { label: '女', value: 'female' }
          ]
        },
        {
          prop: 'birthRange',
          label: '出生日期',
          span: 8,
          formtype: 'DatePicker',
          attrs: {
            type: 'daterange',
            rangeSeparator: '至',
            startPlaceholder: '开始日期',
            endPlaceholder: '结束日期',
            valueFormat: 'yyyy-MM-dd'
          }
        }
      ],
      tableData: [],
      // 分页读 current（不是 pageIndex）
      pagination: {
        current: 1,
        pageSize: 10,
        total: 0
      },
      tableColumns: [
        { prop: 'id', label: 'ID', width: 80 },
        { prop: 'firstName', label: '名', width: 120 },
        { prop: 'lastName', label: '姓', width: 120 },
        { prop: 'email', label: '邮箱' },
        {
          prop: 'image',
          label: '头像',
          width: 80,
          render: (h, { row }) => (
            <el-avatar size="small" src={row.image} />
          )
        }
      ]
    }
  },
  watch: {
    // 条件一变就查（deep 才能捕捉 dateRange 数组内的变化）
    queryFormData: {
      deep: true,
      handler() {
        this.handleSearch()
      }
    }
  },
  created() {
    // 一次性拉全量后缓存在实例上，后续筛选/分页都在本地做
    this.allUsers = null
  },
  methods: {
    async fetchAllUsers() {
      if (!this.allUsers) {
        const res = await fetch('https://dummyjson.com/users?limit=100', { credentials: 'omit' })
        if (!res.ok) throw new Error(\`拉取用户失败：HTTP \${res.status}\`)
        const json = await res.json()
        this.allUsers = json.users || []
      }
      return this.allUsers
    },
    async requestUsers(params) {
      const { pageIndex = 1, pageSize = 10 } = params || {}
      const users = await this.fetchAllUsers()
      // 直接读组件的查询条件而不是 params.formParams：表单是表格的兄弟节点，
      // 翻页请求只带 pageIndex/pageSize，不会带表单值 —— 用 formParams 会让第 2 页丢筛选
      const query = this.queryFormData
      const keyword = String(query.name || '').trim().toLowerCase()

      const rows = users.filter((u) => {
        if (keyword && !\`\${u.firstName}\${u.lastName}\`.toLowerCase().includes(keyword)) return false
        if (query.gender && u.gender !== query.gender) return false
        const range = query.birthRange
        if (Array.isArray(range) && range.length === 2) {
          const birth = String(u.birthDate || '').slice(0, 10)
          const [start, end] = range
          if (!birth || birth < start || birth > end) return false
        }
        return true
      })

      const start = (pageIndex - 1) * pageSize
      return {
        users: rows.slice(start, start + pageSize),
        total: rows.length,
        limit: pageSize,
        skip: start
      }
    },
    // 查询语义 = 回到第 1 页；keepPage: false 由组件内部把 current 置 1
    handleSearch() {
      this.\$refs.tableWithQuery?.httpRequestInstance(this.queryFormData, { keepPage: false })
    }
  }
}
</script>
`
export const RAW_combination_RowApproval = `<template>
  <div>
    <div style="margin-bottom: 12px; color: #909399; font-size: 13px;">
      每行「通过 / 驳回」按钮通过声明式 operate 列 btns 配置；驳回需在弹窗中填写原因；已处理行的按钮自动隐藏
    </div>
    <es-table
      :data-source="data"
      :columns="columns"
      :options="options"
    />
  </div>
</template>

<script lang="jsx">
/**
 * 行审批（组合）—— 声明式 operate 列 btns + 行级状态流转 + 驳回弹窗
 *
 * 关键点：
 *   1. operate 列用声明式 btns 配置：{ name, type, hidden, clickEvent }，
 *      key/prop 为 'operate' 且不写 render 时，EsTable 自动渲染按钮
 *   2. btns 的 hidden 支持函数 (row) => boolean，据行状态动态显隐
 *   3. clickEvent(row) 拿到当前行；驳回复用 useDialog 收集原因后回写状态
 */
import { defineComponent, reactive } from '@vue/composition-api'
import { useDialog } from '@es-plus/vue2'
import { Message } from 'element-ui'

const statusTag = { 待审批: 'warning', 已通过: 'success', 已驳回: 'danger' }

export default defineComponent({
  name: 'CombinationRowApproval',
  setup() {
    const data = reactive([
      { id: 1, applicant: '张三', type: '报销', amount: 1280, status: '待审批', reason: '' },
      { id: 2, applicant: '李四', type: '请假', amount: 0, status: '待审批', reason: '' },
      { id: 3, applicant: '王五', type: '采购', amount: 8600, status: '已通过', reason: '' }
    ])
    const dialog = useDialog()

    const approve = (row) => {
      row.status = '已通过'
      Message.success(\`已通过 \${row.applicant} 的申请\`)
    }

    const reject = (row) => {
      let reason = ''
      dialog({
        title: \`驳回 - \${row.applicant}\`,
        width: '420px',
        // eslint-disable-next-line no-unused-vars -- h 供 JSX 使用（setup 内无 this.\$createElement）
        render: (h) => (
          <el-input
            type="textarea"
            rows={3}
            placeholder="请填写驳回原因"
            value={reason}
            on-input={(v) => { reason = v }}
          />
        ),
        configBtn: [
          { name: '取消', key: 'cancel', click: (_, { close }) => close() },
          {
            name: '确认驳回',
            type: 'danger',
            key: 'confirm',
            click: (_, { close }) => {
              if (!reason.trim()) {
                Message.warning('请填写驳回原因')
                return
              }
              row.status = '已驳回'
              row.reason = reason
              Message.success('已驳回')
              close()
            }
          }
        ]
      })
    }

    const columns = [
      { prop: 'id', label: 'ID', width: 70 },
      { prop: 'applicant', label: '申请人', width: 110 },
      { prop: 'type', label: '类型', width: 100 },
      {
        prop: 'amount',
        label: '金额',
        width: 120,
        render: (h, { row }) => <span>{row.amount ? \`¥\${row.amount}\` : '—'}</span>
      },
      {
        prop: 'status',
        label: '状态',
        width: 110,
        render: (h, { row }) => (
          <el-tag type={statusTag[row.status]} size="small">{row.status}</el-tag>
        )
      },
      { prop: 'reason', label: '驳回原因', render: (h, { row }) => <span>{row.reason || '—'}</span> },
      {
        prop: 'operate',
        label: '操作',
        width: 140,
        btns: [
          { name: '通过', type: 'primary', hidden: (row) => row.status !== '待审批', clickEvent: approve },
          { name: '驳回', type: 'danger', hidden: (row) => row.status !== '待审批', clickEvent: reject }
        ]
      }
    ]

    const options = { border: true }

    return { data, columns, options }
  }
})
</script>
`
