export const RAW_dialog_CachedInstance = `<template>
  <div class="example-dialog-cached">
    <el-button type="primary" @click="open">缓存实例（cacheKey）</el-button>
    <span class="tip">在输入框里写点东西 → 关闭 → 再点一次，内容还在</span>
  </div>
</template>

<script lang="jsx">
/**
 * 实例缓存弹窗 —— cacheKey 让「关闭」不等于「销毁」
 *
 * 关键点：
 *   1. 传 cacheKey 时，关闭只把 visible 置 false，组件实例留在内存里；
 *      再次用同一 cacheKey 打开会复用该实例 —— 表单草稿、滚动位置、tab 选中都还在
 *   2. 缓存实例 10 分钟内没再被打开才真正销毁（每次打开会重新计时）
 *   3. 不传 cacheKey 的弹窗关闭即销毁，这是默认行为，适合纯展示内容
 *
 * 适用：多步表单中途关掉去查资料、审批填写到一半切走、弹窗内嵌有状态的编辑器
 */
import { defineComponent } from '@vue/composition-api'
import { useDialog } from '@es-plus/vue2'

export default defineComponent({
  name: 'DialogCachedInstance',
  setup() {
    const dialog = useDialog()

    const open = () => {
      // 草稿状态放在 render 内部组件里，才能证明「实例复用了、状态没丢」；
      // 若放在 open() 外部，看起来一样但其实是外部状态，说服不了人
      dialog({
        title: '缓存实例（cacheKey）',
        width: '480px',
        cacheKey: 'eui-cached-draft',
        render: (h) => h(DraftBox),
        configBtn: [{ name: '关闭', key: 'close', click: (_, { close }) => close() }]
      })
    }

    return { open }
  }
})

// 草稿组件：text 是它自己的本地 state，实例被复用时不会重新初始化
const DraftBox = {
  name: 'DraftBox',
  data() {
    return { text: '' }
  },
  render(h) {
    return (
      <div style="padding: 20px;">
        <p style="margin-bottom: 10px; color: #606266;">
          关闭后再点一次「缓存实例」，下面输入的内容还在 —— 实例被 cacheKey 缓存住了（10 分钟未再打开才回收）。
        </p>
        <el-input
          value={this.text}
          placeholder="随便输入点什么，关闭再打开看看"
          on-input={(v) => { this.text = v }}
        />
        <p style="margin-top: 10px; color: #909399;">当前输入：{this.text || '（空）'}</p>
      </div>
    )
  }
}
</script>

<style scoped>
.example-dialog-cached {
  display: flex;
  align-items: center;
  gap: 12px;
}
.tip {
  color: #909399;
  font-size: 13px;
}
</style>
`
export const RAW_dialog_Confirm = `<template>
  <div class="example-dialog-confirm">
    <el-button type="danger" @click="confirmDelete">删除确认</el-button>
    <el-button type="warning" @click="confirmPublish">发布确认</el-button>
    <el-button @click="confirmBeforeClose">关闭前拦截</el-button>
    <span class="tip">
      第三个按钮：先在输入框里写点东西，再点右上角 X —— 会先问你「内容还没保存」，选「留下」就关不掉
    </span>
  </div>
</template>

<script lang="jsx">
/**
 * 确认弹窗 —— configBtn 自定义按钮语义 + beforeClose 关闭闸门
 *
 * 关键点：
 *   1. 确认逻辑写在按钮的 click 里，close() 由回调参数给出（不依赖 this）
 *   2. beforeClose(done)：不调用 done() 就不关闭。X 按钮 / 遮罩点击 / ESC，以及
 *      configBtn 里拿到的 close()，走的是同一道闸门（close → handleClose → runBeforeClose）；
 *      确实需要绕过时用弹窗实例暴露的 doClose()
 *   3. 三端（Vue3+Element / Vue3+AntD / Vue2+Element）语义一致
 */
import { defineComponent } from '@vue/composition-api'
import { useDialog } from '@es-plus/vue2'
import { Message, MessageBox, Icon } from 'element-ui'

export default defineComponent({
  name: 'DialogConfirm',
  setup() {
    const dialog = useDialog()

    const confirmDelete = () => {
      dialog({
        title: '确认删除',
        width: '400px',
        render: (h) => (
          <div class="dialog-confirm__row">
            <Icon type="el-icon-warning" class="dialog-confirm__icon dialog-confirm__icon--danger" />
            <div>
              <p class="dialog-confirm__title">确定要删除这条数据吗？</p>
              <p class="dialog-confirm__desc">删除后数据将无法恢复，请谨慎操作。</p>
            </div>
          </div>
        ),
        configBtn: [
          { name: '取消', key: 'cancel', click: (_, { close }) => close() },
          {
            name: '确定删除',
            type: 'danger',
            key: 'confirm',
            click: (_, { close }) => {
              Message.success('删除成功')
              close()
            }
          }
        ]
      })
    }

    const confirmPublish = () => {
      dialog({
        title: '确认发布',
        width: '400px',
        render: (h) => (
          <div class="dialog-confirm__row">
            <Icon type="el-icon-success" class="dialog-confirm__icon dialog-confirm__icon--warning" />
            <div>
              <p class="dialog-confirm__title">确定要发布这篇文章吗？</p>
              <p class="dialog-confirm__desc">发布后将对所有用户可见。</p>
            </div>
          </div>
        ),
        configBtn: [
          { name: '取消', key: 'cancel', click: (_, { close }) => close() },
          {
            name: '立即发布',
            type: 'primary',
            key: 'confirm',
            click: (_, { close }) => {
              Message.success('发布成功')
              close()
            }
          }
        ]
      })
    }

    const confirmBeforeClose = () => {
      // 只要输入过内容就算「有未保存改动」；关闭前拦一道
      let dirty = false
      dialog({
        title: '关闭前拦截',
        width: '460px',
        beforeClose: (done) => {
          if (!dirty) return done()
          MessageBox.confirm('内容还没保存，确定要关闭吗？', '提示', {
            confirmButtonText: '关闭',
            cancelButtonText: '留下',
            type: 'warning'
          })
            .then(() => done())
            .catch(() => { /* 用户选择留在弹窗里 */ })
        },
        render: (h) => (
          <div class="dialog-confirm__body">
            <p class="dialog-confirm__hint">在上面的输入框里写点东西，再点右上角 X 试试。</p>
            <el-input
              type="textarea"
              rows={4}
              placeholder="随便写点什么…"
              on-input={() => { dirty = true }}
            />
          </div>
        ),
        configBtn: [
          { name: '取消', key: 'cancel', click: (_, { close }) => close() },
          {
            name: '保存并关闭',
            type: 'primary',
            key: 'save',
            click: (_, { close }) => {
              // close() 也要过 beforeClose：先把 dirty 清掉，否则「已保存」后还会再问一遍未保存
              dirty = false
              Message.success('已保存')
              close()
            }
          }
        ]
      })
    }

    return { confirmDelete, confirmPublish, confirmBeforeClose }
  }
})
</script>

<style scoped>
.example-dialog-confirm {
  display: flex;
  align-items: center;
  gap: 12px;
}
.tip {
  color: #909399;
  font-size: 13px;
}
</style>

<!--
  弹窗内容是**裸 render 函数**渲染的（不是编译后的模板插槽），调用发生在弹窗宿主组件里、
  再传送到 body —— vnode 上没有本文件的 \`data-v-xxx\`，\`<style scoped>\` 里的
  \`.dialog-confirm__row\` 永远匹配不上（三端同因，docs / pc 的弹窗示例同样处理）。
  所以这里用全局样式，靠 \`dialog-confirm__\` 前缀保证唯一。
-->
<style>
.dialog-confirm__row {
  display: flex;
  align-items: center;
  padding: 20px;
}

.dialog-confirm__icon {
  font-size: 40px;
  margin-right: 16px;
}

.dialog-confirm__icon--danger {
  color: #f56c6c;
}

.dialog-confirm__icon--warning {
  color: #e6a23c;
}

.dialog-confirm__title {
  font-size: 16px;
  margin-bottom: 8px;
}

.dialog-confirm__desc {
  color: #909399;
  font-size: 14px;
}

.dialog-confirm__body {
  padding: 20px;
}

.dialog-confirm__hint {
  margin-bottom: 10px;
  color: #606266;
}
</style>
`
